CREATE OR REPLACE FUNCTION public.fr_road_ride_create(p_from_label text,p_to_label text,p_fare numeric,p_departure_at timestamptz,p_booking_cutoff_at timestamptz DEFAULT NULL,p_route_note text DEFAULT NULL,p_from_lat double precision DEFAULT NULL,p_from_lng double precision DEFAULT NULL,p_to_lat double precision DEFAULT NULL,p_to_lng double precision DEFAULT NULL,p_pickup_radius_km numeric DEFAULT 3) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path TO '' AS $function$ declare v_id uuid; begin if auth.uid() is null then raise exception 'Guest session/login required'; end if; if not exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='driver' and lower(coalesce(p.driver_approval_status,''))='approved') then raise exception 'Approved driver account required'; end if; if length(trim(coalesce(p_from_label,'')))=0 or length(trim(coalesce(p_to_label,'')))=0 then raise exception 'From and To are required'; end if; if p_fare<0 then raise exception 'Fare must be zero or more'; end if; if p_departure_at<=now() then raise exception 'Departure must be in future'; end if; if p_pickup_radius_km<0 or p_pickup_radius_km>25 then raise exception 'Pickup radius invalid'; end if; insert into public.fr_road_rides(driver_id,from_label,to_label,fare,departure_at,booking_cutoff_at,route_note,from_lat,from_lng,to_lat,to_lng,pickup_radius_km) values(auth.uid(),trim(p_from_label),trim(p_to_label),p_fare,p_departure_at,p_booking_cutoff_at,p_route_note,p_from_lat,p_from_lng,p_to_lat,p_to_lng,p_pickup_radius_km) returning id into v_id; insert into public.fr_road_ride_events(ride_id,actor_id,event_type,details) values(v_id,auth.uid(),'road_ride_published',jsonb_build_object('from',p_from_label,'to',p_to_label,'fare',p_fare,'departure_at',p_departure_at)); return v_id; end $function$;
CREATE OR REPLACE FUNCTION public.fr_shared_ride_create(p_vehicle_type text,p_from_label text,p_to_label text,p_total_seats integer,p_price_per_seat numeric,p_departure_at timestamptz,p_booking_cutoff_at timestamptz DEFAULT NULL,p_from_lat double precision DEFAULT NULL,p_from_lng double precision DEFAULT NULL,p_to_lat double precision DEFAULT NULL,p_to_lng double precision DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path TO '' AS $function$ declare v_id uuid; begin if auth.uid() is null then raise exception 'Login required'; end if; if not exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='driver' and lower(coalesce(p.driver_approval_status,''))='approved') then raise exception 'Approved driver account required'; end if; if p_vehicle_type not in ('auto','car') then raise exception 'Vehicle type must be auto or car'; end if; if p_total_seats<1 or p_total_seats>12 then raise exception 'Invalid passenger seat capacity'; end if; if p_price_per_seat<0 then raise exception 'Fare cannot be negative'; end if; if p_departure_at<=now() then raise exception 'Departure must be in the future'; end if; insert into public.fr_shared_rides(driver_id,vehicle_type,from_label,to_label,total_seats,price_per_seat,departure_at,booking_cutoff_at,from_lat,from_lng,to_lat,to_lng) values(auth.uid(),p_vehicle_type,p_from_label,p_to_label,p_total_seats,p_price_per_seat,p_departure_at,p_booking_cutoff_at,p_from_lat,p_from_lng,p_to_lat,p_to_lng) returning id into v_id; insert into public.fr_shared_ride_events(ride_id,actor_id,event_type,details) values(v_id,auth.uid(),'ride_created',jsonb_build_object('vehicle_type',p_vehicle_type,'from',p_from_label,'to',p_to_label,'seats',p_total_seats,'price_per_seat',p_price_per_seat,'departure_at',p_departure_at)); return v_id; end $function$;